import { Pienso } from './../../models/pienso';
import { PiensoService } from './../../services/pienso.service';
import { Component } from '@angular/core';
import { NgForm } from '@angular/forms';
import { UsuarioService } from 'src/app/services/usuario.service';
import { Usuario } from 'src/app/models/usuario';

@Component({
  selector: 'app-panel-admin',
  templateUrl: './panel-admin.component.html',
  styleUrls: ['./panel-admin.component.css']
})
export class PanelAdminComponent {
  constructor(public usuarioService: UsuarioService, public piensoService: PiensoService){
  }

  ngOnInit(){
    this.conseguirUsuarios();
    this.conseguirPiensos();
  }



//USUARIOS
  limpiarUsuario(form?: NgForm){
    if(form){ //si existe el formulario lo vaciamos
      form.reset();
      this.usuarioService.usuarioSeleccionado = new Usuario(); //reseteamos el usuario
    }
  }

  agregarUsuario(form: NgForm){
    if(form.value._id){ //editamos
      this.usuarioService.putUsuario(form.value)
      .subscribe(
        (response: any) => {
          if(response.status === "Usuario actualizado"){
            alert("Usuario editado correctamente");
            this.conseguirUsuarios();
            this.limpiarUsuario(form);
          }else if(response.status === 'El usuario ya existe'){
            console.log('El usuario ya existe', response);
            alert('El usuario con ese email ya existe');
          }
        },
        (error) => {
          console.error("Error al registrar el usuario", error);
        });
    }else{ //agregamos
    //form.value tiene los datos del usuario nuevo
    this.usuarioService.registrarUsuario(form.value)
      .subscribe( 
      (response: any) => { 
        if(response.status === "Usuario registrado correctamente"){
          console.log("Usuario registrado correctamente", response);
          alert('Usuario agregado Correctamente');
          this.conseguirUsuarios();
          this.limpiarUsuario(form);
        }else if(response.status === 'El usuario ya existe'){
          console.log('El usuario ya existe', response);
          alert('El usuario con ese email ya existe');
        }
      },
      (error) => {
        console.error("Error al registrar el usuario", error);
      });
    }
  }

  conseguirUsuarios(){
    this.usuarioService.getUsuarios()
    .subscribe(res => {
      this.usuarioService.usuarios = res as Usuario[];
      console.log(res);
    });
  }

  editarUsuario(usuario: Usuario){
    console.log(usuario._id);
    this.usuarioService.usuarioSeleccionado = usuario;
    //this.usuarioService.putUsuario(usuario)
  }

  eliminarUsuario(_id: string){
    let respuesta = confirm("¿Seguro qué quiere eliminar?");
    if(respuesta){
      this.usuarioService.deleteUsuario(_id)
      .subscribe(res => {
        alert("Usuario eliminado correctamente");
        this.conseguirUsuarios();
      });
    }
  }



  //PIENSOS
  limpiarPienso(form?: NgForm){
    if(form){ //si existe el formulario lo vaciamos
      form.reset();
      this.piensoService.piensoSeleccionado = new Pienso(); //reseteamos el usuario
    }
  }

  agregarPienso(form: NgForm){
    if(form.value._id){ //editamos
      this.piensoService.putPienso(form.value)
      .subscribe(
        (res:any) => {
        if(res.status === "Pienso actualizado"){
          console.log("Pienso editado", res);
          alert("Pienso editado correctamente");
          this.conseguirPiensos();
          this.limpiarPienso(form);
        }else if(res.status === "El nombre del pienso no se puede repetir"){
          console.log("Pienso repetido", res);
          alert("El nombre del pienso ya existe en la base de datos");
        }
      },
      (error)=>{
        console.log("error al editar el pienso",error);
      })
    }else{ //agregamos
    //form.value tiene los datos del usuario nuevo
    this.piensoService.postPienso(form.value)
      .subscribe(
        (res:any) => {
          if(res.status === "Pienso guardado"){
            console.log("Pienso guardado", res);
            alert("Pienso agregado correctamente");
            this.conseguirPiensos();
            this.limpiarPienso(form);
          }else if(res.status === "El nombre del pienso no se puede repetir"){
            console.log("Pienso repetido", res);
            alert("El nombre del pienso ya existe en la base de datos");
          }
        },
        (error)=>{
          console.log("error al agregar el pienso",error);
        }
        );
    }
  }

  conseguirPiensos(){
    this.piensoService.getPiensos()
    .subscribe(res => {
      this.piensoService.piensos = res as Pienso[];
      console.log(res);
    });
  }


  editarPienso(pienso: Pienso){
    console.log(pienso._id);
    this.piensoService.piensoSeleccionado = pienso;

  }

  eliminarPienso(_id: string){
    let respuesta = confirm("¿Seguro qué quiere eliminar?");
    if(respuesta){
      this.piensoService.deletePienso(_id)
      .subscribe(res => {
        alert("Pienso eliminado correctamente");
        this.conseguirPiensos();
      });
    }
  }

}
<!--MENÚ-->
<div class="menu container-fluid" id="menuAdmin" style="display:none">
    <a href="#panelAdmin-usuarios" class="menu-item">Usuarios</a>
    <a href="#panelAdmin-piensos" class="menu-item">Piensos</a>
    <a href="#fin" class="menu-item">Comprar</a>
  </div>

<!--FORMULARIO USUARIOS-->
<div class="row" id="panelAdmin-usuarios" style="display:none">
    <div class="col s2">
        <form class="card card-body" #usuarioForm="ngForm" (ngSubmit)="agregarUsuario(usuarioForm)"> <!--Hacemos un método que va a recoger todo los valores de los inputs-->
            <h3>Usuarios:</h3>
            <input type="hidden" name="_id" #_id="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado._id">
            <div>
                <label class="form-label">Nombre Completo:</label>
                <input type="text" class="form-control" name="nombreCompleto" #nombreCompleto="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.nombreCompleto">
            </div>
            <div>
                <label class="form-label">Dirección:</label>
                <input type="text" class="form-control"  name="direccion"  #direccion="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.direccion">
            </div>
            <div>
                <label class="form-label">Telefono:</label>
                <input type="tlf" class="form-control" name="telefono" #telefono="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.telefono">
            </div>
            <div>
                <label class="form-label">Email:</label>
                <input type="email" class="form-control" placeholder="nombre@email.com" name="email" #email="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.email">
            </div>
            <div>
                <label class="form-label">Contraseña:</label>
                <input type="password" class="form-control" name="password" #password="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.password">
            </div>
            <div>
                <label class="form-label">Rol:</label>
                <select class="form-control" name="rol" #rol="ngModel" [(ngModel)]="usuarioService.usuarioSeleccionado.rol">
                    <option value="Administrador">Administrador</option>
                    <option value="Cliente">Cliente</option>
                </select>
            </div>
            <input type="button" class="btn btn-primary" style="margin: 3%;" (click)="agregarUsuario(usuarioForm)"  value="Guardar">
            <input type="button" class="btn btn-primary" style="margin: 3%;" (click)="limpiarUsuario(usuarioForm)" value="Limpiar">
        </form>
    </div>
    <div class="col s10">
        <table class="table" style="font-size: 12px;">
            <thead>
                <th>Nombre</th>
                <th>Dirección</th>
                <th>Teléfono</th>
                <th>Email</th>
                <th>Contraseña</th>
                <th>Rol</th>
            </thead>
            <tbody>
                <tr *ngFor="let usuario of usuarioService.usuarios">
                    <td>{{usuario.nombreCompleto}}</td>
                    <td>{{usuario.direccion}}</td>
                    <td>{{usuario.telefono}}</td>
                    <td>{{usuario.email}}</td>
                    <td>{{usuario.password}}</td>
                    <td>{{usuario.rol}}</td>
                    <td style="font-size: 18px;">
                        <a (click)="editarUsuario(usuario)"><i class="bi bi-pencil-square" style="color:deepskyblue; font"></i></a>
                        <a (click)="eliminarUsuario(usuario._id)"><i class="bi bi-trash3" style="color:crimson"></i></a>
                    </td>
                </tr>
            </tbody>
        </table>
    </div>
</div>



<!--FORMULARIO PIENSO-->
<div class="row" id="panelAdmin-piensos" style="display:none">
    <div class="col s2">
        <form class="card card-body" #piensoForm="ngForm" (ngSubmit)="agregarPienso(piensoForm)"> <!--Hacemos un método que va a recoger todo los valores de los inputs-->
            <h3>Piensos:</h3>
            <input type="hidden" name="_id" #_id="ngModel" [(ngModel)]="piensoService.piensoSeleccionado._id">

            <div>
              <label class="form-label">Imagen:</label>
              <input type="text" class="form-control" name="imagen" #imagen="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.imagen">
          </div>

            <div>
                <label class="form-label">Nombre:</label>
                <input type="text" class="form-control" name="nombre" #nombre="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.nombre">
            </div>
        
            <div>
                <label class="form-label">Tipo Animal:</label>
                <select class="form-control" name="tipoAnimal" #tipoAnimal="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.tipoAnimal">
                    <option value="Gato">Gato</option>
                    <option value="Perro">Perro</option>
                </select>
            </div>

            <div>
                <label class="form-label">Marca:</label>
                <input type="text" class="form-control" name="marca" #marca="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.marca">
            </div>

            <div>
                <label class="form-label">Precio:</label>
                <input type="number" class="form-control"  name="precio" #precio="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.precio" min="0.1">
            </div>

            <div>
                <label class="form-label">Stock:</label>
                <input type="number" class="form-control" name="stock" #stock="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.stock" min="1">
            </div>

            <div>
                <label class="form-label">Descripcion:</label>
                <input type="text" class="form-control" name="descripcion" #descripcion="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.descripcion">
            </div>

            <div>
              <label class="form-label">Peso:</label>
              <input type="number" class="form-control" name="peso" #peso="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.peso" min="0.1">
            </div>

            <div>
                <label class="form-label">Edad:</label>
                <select class="form-control" name="edad" #edad="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.edad">
                    <option value="Junior">Junior</option>
                    <option value="Adulto">Adulto</option>
                    <option value="Senior">Senior</option>
                </select>
            </div>

            <div>
                <label class="form-label">Sabor:</label>
                <select class="form-control" name="sabor" #sabor="ngModel" [(ngModel)]="piensoService.piensoSeleccionado.sabor">
                    <option value="Pollo">Pollo</option>
                    <option value="Pescado">Pescado</option>
                    <option value="Buey">Buey</option>
                    <option value="Ternera">Ternera</option>
                    <option value="Conejo">Conejo</option>
                </select>
            </div>

            <input type="button" class="btn btn-primary" style="margin: 3%;" (click)="agregarPienso(piensoForm)"  value="Guardar">
            <input type="button" class="btn btn-primary" style="margin: 3%;" (click)="limpiarPienso(piensoForm)" value="Limpiar">
        </form>
    </div>
    <div class="col s10">
        <table class="table" style="font-size: 12px;">
            <thead>
                <th>Imagen</th>
                <th>Nombre</th>
                <th>Tipo Animal</th>
                <th>Marca</th>
                <th>Precio</th>
                <th>Stock</th>
                <th>Descripcion</th>
                <th>Peso</th>
                <th>Edad</th>
                <th>Sabor</th>
            </thead>
            <tbody>
                <tr *ngFor="let pienso of piensoService.piensos">
                    <td>{{pienso.imagen}}</td>
                    <td>{{pienso.nombre}}</td>
                    <td>{{pienso.tipoAnimal}}</td>
                    <td>{{pienso.marca}}</td>
                    <td>{{pienso.precio}}</td>
                    <td>{{pienso.stock}}</td>
                    <td>{{pienso.descripcion}}</td>
                    <td>{{pienso.peso}}</td>
                    <td>{{pienso.edad}}</td>
                    <td>{{pienso.sabor}}</td>
                    <td style="font-size: 18px;">
                        <a (click)="editarPienso(pienso)"><i class="bi bi-pencil-square" style="color:deepskyblue"></i></a>
                        <a (click)="eliminarPienso(pienso._id)"><i class="bi bi-trash3" style="color:crimson"></i></a>
                    </td>
                </tr>
            </tbody>
        </table>
    </div>
</div>

<div id="fin"></div>
